import{_ as a,o as n,a as p,b as l}from"./app.BGziXukh.js";const v=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"同步控制","link":"/api/SIMD-API/basic_api/sync_control/sync_control"},{"text":"核间同步","link":"/api/SIMD-API/basic_api/sync_control/inter_core_sync/inter_core_sync"},{"text":"GroupBarrier","link":"/api/SIMD-API/basic_api/sync_control/inter_core_sync/GroupBarrier"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/sync_control/inter_core_sync/GroupBarrier.md","filePath":"api/SIMD-API/basic_api/sync_control/inter_core_sync/GroupBarrier.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1795433446000}'),c={name:"api/SIMD-API/basic_api/sync_control/inter_core_sync/GroupBarrier.md"};function t(r,s,e,i,o,d){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>GroupBarrier</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR&amp;950DT系列产品：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为<code>&quot;basic_api/core_mng/roc/kernel_operator_group_barrier_intf.h&quot;</code>。</p><p>当同一个<a href="../../inter_core_communication/CubeResGroupHandle/CubeResGroupHandle.html">CubeResGroupHandle</a>中的两个AIV任务之间存在依赖关系时，可以使用GroupBarrier控制同步。假设一组AIV A做完任务x以后，另外一组AIV B才可以开始后续业务，称AIV A组为Arrive组，AIV B组为Wait组。</p><p>GroupBarrier提供以下接口：</p><ul><li><span id="constructor"></span><strong>GroupBarrier</strong>：创建GroupBarrier对象，通过设置构造函数参数，确定Arrive组的Block个数和Wait组的Block个数。</li><li><span id="arrive"></span><strong>Arrive</strong>：通知其他等待的AIV，本AIV已经完成其依赖的任务。</li><li><span id="wait"></span><strong>Wait</strong>：阻塞当前AIV，直到Arrive组的AIV均完成依赖任务后，再开始执行后续任务。</li><li><span id="get-workspace-len"></span><strong>GetWorkspaceLen</strong>：返回当前GroupBarrier所占用的Global Memory消息空间大小。</li></ul><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="n">PipeMode</span><span class="w"> </span><span class="n">pipeMode</span><span class="o">&gt;</span>
<span class="k">class</span><span class="w"> </span><span class="nc">GroupBarrier</span><span class="w"> </span><span class="p">{</span>
<span class="k">public</span><span class="o">:</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="n">GroupBarrier</span><span class="p">(</span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">groupWorkspace</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">arriveSizeIn</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">waitSizeIn</span><span class="p">);</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Arrive</span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">arriveIndex</span><span class="p">);</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Wait</span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">waitIndex</span><span class="p">);</span>
<span class="w">    </span><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">GetWorkspaceLen</span><span class="p">();</span>
<span class="p">};</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 类模板参数说明</p><table><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td>pipeMode</td><td>GroupBarrier发送组同步消息时使用的执行单元，仅支持MTE3_MODE。</td></tr></tbody></table><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">enum</span><span class="w"> </span><span class="k">class</span><span class="w"> </span><span class="nc">PipeMode</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">SCALAR_MODE</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span>
<span class="w">    </span><span class="n">MTE3_MODE</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span>
<span class="w">    </span><span class="n">MAX</span>
<span class="p">};</span>
</code></pre></div><p><strong>表2</strong> 构造函数和成员函数参数说明</p><table><thead><tr><th>接口</th><th>参数</th><th>输入/输出</th><th>说明</th></tr></thead><tbody><tr><td>GroupBarrier</td><td>groupWorkspace</td><td>输入</td><td>该GroupBarrier在GM上的起始地址，用于存储组同步消息，必须512B对齐。用户自行管理这部分GlobalMemory，包括地址对齐和清零。</td></tr><tr><td>GroupBarrier</td><td>arriveSizeIn</td><td>输入</td><td>Arrive组AIV个数。</td></tr><tr><td>GroupBarrier</td><td>waitSizeIn</td><td>输入</td><td>Wait组AIV个数。</td></tr><tr><td>Arrive</td><td>arriveIndex</td><td>输入</td><td>该AIV在Arrive组的序号。范围为[0, arriveSize - 1]。</td></tr><tr><td>Wait</td><td>waitIndex</td><td>输入</td><td>该AIV在Wait组的序号。范围为[0, waitSize - 1]。</td></tr></tbody></table><p>GetWorkspaceLen无参数。</p><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><table><thead><tr><th>接口</th><th>返回值</th></tr></thead><tbody><tr><td>GroupBarrier</td><td>GroupBarrier对象实例。</td></tr><tr><td>Arrive</td><td>无。</td></tr><tr><td>Wait</td><td>无。</td></tr><tr><td>GetWorkspaceLen</td><td>当前GroupBarrier所占用的Global Memory消息空间大小。</td></tr></tbody></table><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li><p>GroupBarrier构造函数的约束如下：</p><ul><li>使用该构造函数时，Unified Buffer（UB）空间末尾的1600B被占用。</li><li>不能和<a href="../../../adv_api/cube_compute/Matmul_Kernel/REGIST_MATMUL_OBJ.html">REGIST_MATMUL_OBJ</a>接口同时使用。使用资源管理API时，用户自主管理AIC和AIV的核间通信，REGIST_MATMUL_OBJ内部是由框架管理AIC和AIV的核间通信，同时使用可能会导致通信消息错误等异常。</li></ul></li><li><p>Arrive、Wait：支持在循环中使用，但是受限于多核间通信效率要求，循环最大次数不超过1,048,575次。</p></li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p><span id="usage"></span></p><p>基于GroupBarrier的组同步使用步骤如下：</p><ol><li>创建GroupBarrier，并为其分配满足对齐要求且已清零的GlobalMemory空间。</li><li>被等待的AIV调用Arrive，需要等待的AIV调用Wait。</li><li>调用GetWorkspaceLen查询GroupBarrier所需的workspace大小。</li></ol><p>以下kernel示例中，Block 0和Block 1属于Arrive组，Block 2至Block 7属于Wait组。workspace由调用方分配512B对齐且已清零的3072B空间。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">ARRIVE_NUM</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">WAIT_NUM</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">6</span><span class="p">;</span>

<span class="k">extern</span><span class="w"> </span><span class="s">&quot;C&quot;</span><span class="w"> </span><span class="n">__global__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">GroupBarrierKernel</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">workspace</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GroupBarrier</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">PipeMode</span><span class="o">::</span><span class="n">MTE3_MODE</span><span class="o">&gt;</span><span class="w"> </span><span class="n">barrier</span><span class="p">(</span><span class="n">workspace</span><span class="p">,</span><span class="w"> </span><span class="n">ARRIVE_NUM</span><span class="p">,</span><span class="w"> </span><span class="n">WAIT_NUM</span><span class="p">);</span>
<span class="w">    </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">workspaceLen</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">barrier</span><span class="p">.</span><span class="n">GetWorkspaceLen</span><span class="p">();</span>
<span class="w">    </span><span class="p">(</span><span class="kt">void</span><span class="p">)</span><span class="n">workspaceLen</span><span class="p">;</span>

<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">blockIdx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GetBlockIdx</span><span class="p">();</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">blockIdx</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">ARRIVE_NUM</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="c1">// Arrive-group vector operations go here.</span>
<span class="w">        </span><span class="n">barrier</span><span class="p">.</span><span class="n">Arrive</span><span class="p">(</span><span class="n">blockIdx</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span><span class="w"> </span><span class="k">else</span><span class="w"> </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">blockIdx</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">ARRIVE_NUM</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">WAIT_NUM</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">barrier</span><span class="p">.</span><span class="n">Wait</span><span class="p">(</span><span class="n">blockIdx</span><span class="w"> </span><span class="o">-</span><span class="w"> </span><span class="n">ARRIVE_NUM</span><span class="p">);</span>
<span class="w">        </span><span class="c1">// Wait-group vector operations go here.</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>调用该kernel时，blockDim需设置为8。GroupBarrier需要的workspace大小为3072B，可通过GetWorkspaceLen查询。workspaceLen为设备侧查询结果，实际分配workspace应由调用方在host侧完成。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>workspaceLen = 3072
</code></pre></div><p>结果示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>占用的GlobalMemory空间(offset)的大小为: 3072
</code></pre></div></article></div>`,1)])])}const _=a(c,[["render",t]]);export{v as __pageData,_ as default};
